function createCounter(start) {
  let count = start;
  return {
    inc() {
      count += 1;
    },
    dec() {
      count -= 1;
    },
    value() {
      return count;
    },
  };
}

const a = createCounter(10);
const b = createCounter(0);
a.inc();
a.inc();
b.inc();
a.dec();
console.log(a.value(), b.value(), a.count);

